from pathlib import Path
from datetime import datetime
import shutil
import base64
import zlib

# =========================================================
# VETMAP - APLICAR FORMATO V18 TIENDA + VETERINARIA
# =========================================================
# Este script:
# 1) Busca ProyectoVetMap automáticamente.
# 2) Crea respaldo de main.jsx e index.css.
# 3) Aplica el nuevo dashboard V18 para Tienda y Veterinaria.
# 4) NO toca backend, base de datos, api.js ni credenciales.
# =========================================================

MAIN_PAYLOAD = """"""
CSS_PAYLOAD = """"""

def encontrar_raiz():
    bases = [
        Path.cwd(),
        Path(__file__).resolve().parent,
        Path(__file__).resolve().parent.parent,
    ]

    revisados = set()

    for base in bases:
        for root in [base, *base.parents]:
            if root in revisados:
                continue
            revisados.add(root)

            main = root / "web" / "src" / "main.jsx"
            css = root / "web" / "src" / "index.css"

            if main.exists() and css.exists():
                return root

    raise FileNotFoundError(
        "No encontré web/src/main.jsx e index.css.\n"
        "Pon este .py dentro de ProyectoVetMap o ejecútalo desde esa carpeta."
    )

root = encontrar_raiz()
main_path = root / "web" / "src" / "main.jsx"
css_path = root / "web" / "src" / "index.css"

print("VetMap detectado en:")
print(root)
print()

timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
backup_dir = root / "respaldos_vetmap" / f"antes_v18_{timestamp}"
backup_dir.mkdir(parents=True, exist_ok=True)

shutil.copy2(main_path, backup_dir / "main.jsx")
shutil.copy2(css_path, backup_dir / "index.css")

print("Respaldo creado:")
print(backup_dir)
print()

nuevo_main = zlib.decompress(base64.b64decode(MAIN_PAYLOAD))
nuevo_css = zlib.decompress(base64.b64decode(CSS_PAYLOAD))

main_path.write_bytes(nuevo_main)
css_path.write_bytes(nuevo_css)

print("==========================================")
print(" VETMAP V18 APLICADO CORRECTAMENTE")
print("==========================================")
print()
print("Modificado:")
print(" - web/src/main.jsx")
print(" - web/src/index.css")
print()
print("NO se modificó:")
print(" - backend")
print(" - base de datos")
print(" - api.js")
print(" - usuarios / credenciales")
print()
print("Recarga la web con Ctrl + F5.")
